const uint8_t *glyphs_for_char(uint8_t character)
{
    if (character < GLYPH_FIRST_CHAR || character > GLYPH_LAST_CHAR) {
        character = (uint8_t)'?';
    }
    return g_glyphs_ascii[character - GLYPH_FIRST_CHAR];
}
